mapper.insert:
INSERT INTO crm_contact_pool_automation_cursor (tenant_id, last_pool_id)
VALUES (#{tenantId}, NULL)
ON DUPLICATE KEY UPDATE tenant_id = #{tenantId}

mapper.select:
SELECT membership.pool_id AS poolId, COUNT(*) AS contactCount FROM crm_contact_pool_membership membership WHERE membership.tenant_id = #{tenantId} AND membership.pool_id IN
#{poolId}
GROUP BY membership.pool_id

mapper.update:
UPDATE crm_contact_pool_membership
SET pool_id = #{targetPoolId}
WHERE tenant_id = #{tenantId}
  AND pool_id = #{sourcePoolId}

mapper.select:
SELECT c.id FROM crm_contact c WHERE c.tenant_id = #{tenantId} AND c.status = 'ACTIVE' AND c.updated_time <= #{cutoff}
AND c.deal_status <> 'WON'
AND NOT EXISTS ( SELECT 1 FROM crm_contact_pool_membership current_pool WHERE current_pool.tenant_id = c.tenant_id AND current_pool.contact_id = c.id ) AND ( EXISTS ( SELECT 1 FROM crm_contact_pool_eligible_member eligible_member WHERE eligible_member.tenant_id = c.tenant_id AND eligible_member.pool_id = #{poolId} AND eligible_member.actor_id = c.owner_actor_id ) OR EXISTS ( SELECT 1 FROM organization_membership owner_membership JOIN crm_contact_pool_eligible_department eligible_department ON eligible_department.tenant_id = owner_membership.tenant_id AND eligible_department.department_id = owner_membership.department_id AND eligible_department.pool_id = #{poolId} WHERE owner_membership.tenant_id = c.tenant_id AND owner_membership.actor_id = c.owner_actor_id AND owner_membership.status = 'ACTIVE' ) ) ORDER BY c.updated_time ASC, c.id ASC LIMIT #{limit}
